package cn.zhuatech.apistudio.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.net.URI;import java.util.*;
@Service public class RequestPlanService{public Result plan(Request r){List<String>warnings=new ArrayList<>();int risk=0;String method=r.method().toUpperCase();if(List.of("DELETE","PATCH","PUT").contains(method)){risk+=35;warnings.add("请求可能修改或删除远端数据");}try{URI u=URI.create(r.url());if(!List.of("localhost","127.0.0.1").contains(u.getHost())){risk+=15;warnings.add("目标为外部网络地址");}}catch(Exception e){risk+=70;warnings.add("URL 格式无效");}if(r.timeoutSeconds()>30){risk+=15;warnings.add("超时时间较长");}if(r.body()!=null&&r.body().length()>100000){risk+=20;warnings.add("请求体超过 100 KB");}String curl="curl -X "+method+" '"+r.url().replace("'","")+"' -H 'Content-Type: application/json'"+(r.body()==null||r.body().isBlank()?"":" --data '<request-body>'");String level=risk>=60?"HIGH":risk>=25?"MEDIUM":"LOW";if(warnings.isEmpty())warnings.add("请求参数未发现明显风险");return new Result(curl,Math.min(100,risk),level,new MockResponse(r.mockStatus(),r.mockDelayMs(),Map.of("success",true,"source","ZhuaTech APIStudio")),warnings);}
 public record Request(@Pattern(regexp="(?i)GET|POST|PUT|PATCH|DELETE") String method,@NotBlank String url,String body,@Min(1) @Max(120) int timeoutSeconds,@Min(100) @Max(599) int mockStatus,@Min(0) @Max(30000) int mockDelayMs){}public record MockResponse(int status,int delayMs,Map<String,Object> body){}public record Result(String curlPreview,int riskScore,String riskLevel,MockResponse mock,List<String>warnings){} }
